function validate([nums, m]) {
  if (!Number.isInteger(m) || m < 1 || m > 17) return 'm is between 1 and 17.';
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 2 ** m) return 'nums needs between 2 and 2^m values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v >= 2 ** m)) return 'Each value is between 0 and 2^m - 1.';
  return null;
}

