function maxHammingDistances(nums, m) {
  const size = 1 << m;
  const mask = size - 1;
  const dist = new Array(size).fill(-1);
  const queue = [];
  for (const num of nums) {
    if (dist[num] === -1) {
      dist[num] = 0;
      queue.push(num);
    }
  }
  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    for (let bit = 0; bit < m; bit++) {
      const next = node ^ (1 << bit);
      if (dist[next] === -1) {
        dist[next] = dist[node] + 1;
        queue.push(next);
      }
    }
  }
  return nums.map(num => m - dist[num ^ mask]);
}

