function maxHammingDistances(nums, m) {
  const bitsSet = x => x.toString(2).split('').filter(c => c === '1').length;
  return nums.map((a, i) => {
    let best = 0;
    nums.forEach((b, j) => { if (j !== i) best = Math.max(best, bitsSet(a ^ b)); });
    return best;
  });
}

