function generate(rand, size) {
  const m = size === 'large' ? 11 + Math.floor(rand() * 7) : 1 + Math.floor(rand() * 5);
  const limit = 2 ** m;
  const n = size === 'large' ? Math.min(2000, limit) : 2 + Math.floor(rand() * (Math.min(limit, 8) - 1));
  // Sometimes keep the values inside a few allowed bits so the distances stay small.
  let allowed = limit - 1;
  if (rand() < 0.4) allowed = Math.floor(rand() * limit);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * limit) & allowed);
  return [nums, m];
}
